INSERT INTO languages
    (name, description, focus, category, classification, feature, tags, themes)
VALUES
    ('German', 'Baseline: reflexively pushes toward the causal chain and imposes origin, cause and rank before the subject matter is considered', 'Causal chain and genealogical ordering', 'Language', 'fusional language / genealogical tendency', 'Tense is obligatory on almost every verb; subject acts, object suffers, clause justifies', '["causal", "genealogical", "hierarchy", "tense", "baseline"]', '["Causality", "Agency & control", "Rank & salience", "Time & aspect"]'),
    ('English', 'Pushes toward shorter, parallel units instead of nested causal constructions and reveals things side by side where German stacks them', 'Parallel, short units', 'Language', 'analytic language', 'Prefers parataxis over deep hypotaxis', '["parallel", "parataxis", "coordination"]', '["Coexistence"]'),
    ('Greenlandic (Kalaallisut)', 'Thinking operates in holistic state descriptions rather than mechanical building blocks', 'Embedding the agent in the relational whole event', 'Language', 'Eskimo-Aleut / polysynthetic-ergative', 'A single highly modified word-stem construct depicts the whole situation instead of isolated subjects and verbs', '["polysynthetic", "ergative", "holistic"]', '["Agency & control", "Coexistence"]'),
    ('Ainu', 'No syntactic distance between tool, target and action; breaks the split between actor and acted-upon', 'Fusion of object and action', 'Language', 'isolate (Japan) / incorporating & appositional', 'The direct object is morphologically fixed inside the verb body ("I knife-cut-meat")', '["incorporating", "object", "fusion"]', '["Rank & salience"]'),
    ('Nez Percé (Nimipuutímt)', 'Makes it impossible to unconsciously equate "existing" (intransitive) with "acting upon" (transitive)', 'Absolute relational symmetry of all sentence parts', 'Language', 'Plateau Penutian / tripartite case system', 'Marks intransitive subject, transitive subject and transitive object with three distinct forms', '["tripartite", "case", "symmetry"]', '["Agency & control"]'),
    ('Guugu Yimithirr', 'Eliminates the ego as the egocentric zero point of space grammatically', 'Cosmic rather than egocentric grasp of space', 'Language', 'Pama-Nyungan (Australia) / absolute geocentric orientation', 'Has no left/right/front/back; every spatial relation via cardinal directions', '["cardinal-direction", "ego-less", "geocentric"]', '["Space & orientation"]'),
    ('Burushaski', 'Protects against treating accidents conceptually like intentions', 'Grading of involuntary vs. intentional causation', 'Language', 'isolate (Pakistan) / ergative split', 'Marking switches by whether an action was deliberately controlled or an involuntary reflex (sneezing vs. calling)', '["ergative", "intentionality", "involuntary"]', '["Causality", "Agency & control"]'),
    ('Aymara', 'Radically reverses the Western metaphor of striding forward into the future', 'Inverted time metaphor; visibility as an axis', 'Language', 'Aymara family (Andes) / inverted time metaphor', 'The future lies behind the speaker (unseen), the past in front (known, visible)', '["time-metaphor", "visibility", "inverted-time"]', '["Time & aspect"]'),
    ('Classical Chinese (Wényán)', 'Causality is not forced morphologically but emerges topologically from parallelism and symmetry', 'Pure relational constellation in the now', 'Language', 'Sino-Tibetan / context-dependent functional fluidity', 'No inflection, no gender, no explicit tense; a character can be noun, verb or adjective', '["isolating", "fluidity", "parallelism"]', '["Coexistence", "Causality"]'),
    ('Guaraní', 'Couples temporality directly to the essence of things instead of to verbs', 'Temporal transience of matter', 'Language', 'Tupí-Guaraní / nominal aspect (tense on nouns)', 'Nouns are conjugated: "ex-house" (-kue), "future house" (-rã)', '["nominal-aspect", "matter", "transience"]', '["Time & aspect", "Object boundaries"]'),
    ('Pirahã', 'Forces restriction to the immediately perceivable and rules out abstract, hypothetical causal nesting', 'Absolute empirical present', 'Language', 'Mura family / radical grammatical immediacy', 'No recursion, no abstract color terms, no number words', '["immediacy", "recursion-free", "empirical"]', '["Time & aspect"]'),
    ('Maya-Zutuhil', 'Demands the degree of completion of a state instead of the point in time', 'Degree of completion of a system state', 'Language', 'Mayan family / terminative aspect structure', 'Ignores the when; encodes whether an action was just initiated, is saturated, or completed as an irreversible transformation', '["aspect", "completion", "terminative"]', '["Time & aspect"]'),
    ('Tariana', 'Forces every statement to disclose its source of information grammatically', 'Relentless source-criticism in syntax', 'Language', 'Arawakan family / hyper-evidentiality', 'Even stricter than Tuyuca; without the exact ending for hearsay/inference a statement counts syntactically as a lie', '["evidentiality", "source", "hearsay"]', '["Evidence & certainty"]'),
    ('Kwakiutl (Kwak''wala)', 'Substances cannot be thought without their visibility status', 'Spatial visibility of the information object', 'Language', 'Wakashan / obligatory epistemic localization', 'For every object it must be carried whether it is visible/invisible and near the speaker or the hearer', '["visibility", "deixis", "localization"]', '["Evidence & certainty", "Space & orientation"]'),
    ('Hua (Yagaria)', 'The recipient''s cognition is a syntactic part of one''s own sentence production', 'Psychological state of the counterpart', 'Language', 'Trans-New Guinea / anticipatory modal conjugation', 'Verb forms change by expected agreement, doubt or rejection of the listener', '["modal", "anticipation", "addressee"]', '["Perspective & reciprocity"]'),
    ('Nganasan', 'Protects the cognitive system from mixing meta-levels', 'Linguistic separation of reality and simulation', 'Language', 'Samoyedic (Uralic) / imaginative and hypothetical evidentials', 'Special moods mark whether something is real, dreamed, a hallucination, or a conscious myth', '["evidentiality", "mood", "dream"]', '["Evidence & certainty"]'),
    ('Inuktitut', 'Prevents the blurring of contexts in spatial references', 'Fragmentation of space and materiality', 'Language', 'Eskimo-Aleut / locative and phenomenological classes', 'No abstract umbrella terms for space; forces whether an open unbounded space or a closed 3D body', '["space", "materiality", "classes"]', '["Space & orientation", "Object boundaries"]'),
    ('Ojibwe (animacy hierarchy)', 'Breaks the Western reduction of nature to dead matter', 'Presence of spiritual/dynamic life force', 'Language', 'Algonquian family / animacy hierarchy', 'Grammatical animate/inanimate instead of gender; stones, thunder, certain trees shift into the animate class', '["animacy", "animate", "nature"]', '["Object boundaries"]'),
    ('Ojibwe (obviation)', 'Forces one discourse-wide decision about whose account this is and marks every mention of the others as secondary, so a report cannot drift silently between the parties it speaks about', 'Which of several third parties the account is about', 'Language', 'Algonquian family / proximate-obviative marking', 'Among animate third persons exactly one is proximate and stays unmarked while every other one carries the obviative suffix for as long as the passage runs; "John and Bill were friends ever since he first saw him" cannot be formed without settling who saw whom', '["obviation", "proximate", "obviative", "salience", "discourse-scope", "third-person"]', '["Perspective & reciprocity"]'),
    ('Walbiri (Warlpiri)', 'Frees thinking from sequential linearity and reads sentences as associative clusters', 'Non-hierarchical, network-like arrangement of information', 'Language', 'Pama-Nyungan / radical syntactic freedom (scrambling)', 'Word order irrelevant; function purely via suffixes, sentence parts freely scattered', '["scrambling", "free-word-order", "network"]', '["Coexistence", "Rank & salience"]'),
    ('Thai', 'No statement without first balancing the relational structure of those involved', 'Exact sociometric position in the social web', 'Language', 'Kra-Dai / relational-hierarchical pronoun system', 'Dozens of words for "I" and "you" by age, status, kinship, emotional distance', '["pronoun", "status", "social"]', '["Perspective & reciprocity", "Rank & salience"]'),
    ('Sanskrit (nominal compound)', 'Replaces linear syntax with one monumental conceptual network', 'Nesting concepts into one synchronic unit', 'Language', 'Indo-European (Indo-Aryan) / nominal compound (samāsa)', 'Endless samāsas freeze complex causal and philosophical relations into a single term', '["compound", "samasa", "nesting", "condensation"]', '["Coexistence"]'),
    ('Sanskrit (Syādvāda)', 'Leads out of the binary true/false tunnel and allows contradictory system states at once', 'Multidimensional relativity of truth', 'Language', 'Indian logic philosophy (Jaina) / sevenfold predication', 'Knows seven truth values ("maybe it is", "maybe it is not", "maybe indescribable" …)', '["logic", "syadvada", "many-valued"]', '["Logic & ambiguity"]'),
    ('Hindi-Urdu (vector verbs)', 'Forces stating not only that an action is finished but whom its outcome falls to and how it came about', 'Direction of benefit and manner of completion', 'Language', 'Indo-Aryan / explicator compound verbs', 'A semantically bleached second verb attaches to the main verb: kar denā (done for another), kar lenā (done for oneself), kar baiṭhnā (done inadvertently), kar ḍālnā (done forcefully and irreversibly)', '["vector-verb", "benefactive", "completion", "disposition"]', '["Time & aspect", "Agency & control"]'),
    ('Turkish (stacked causatives)', 'Forces stating how many links stand between the one who speaks and the one who acted, so a delegated act cannot be reported as a first-degree event', 'Depth of the delegation chain', 'Language', 'Turkic / recursive causative stacking', 'The causative suffix reapplies to its own output: yap (do), yaptır (have done), yaptırt (have someone have it done), yaptırttır (one link further); each step inserts a further instigator between the speaker and the hands that acted', '["causative", "stacking", "delegation", "recursion", "agent-chain"]', '["Causality", "Agency & control"]'),
    ('Mongolian (reflexive possession)', 'Leaves no possessive and no chained clause anchorless: every "the" and every "and then" must declare whether it stays with the one already acting or hands over to another', 'Whether the one already acting stays the anchor', 'Language', 'Mongolic / reflexive-possessive reference tracking', 'The reflexive-possessive -AA binds a possessor or an embedded subject to the subject of the matrix clause, while the third-person possessive ni marks it as someone else; the same reflexive vs. non-reflexive contrast tracks reference across converb chains in Tungusic (Evenki, Ėven)', '["reflexive-possessive", "coreference", "reference-tracking", "switch-reference", "anchor"]', '["Possession & belonging", "Rank & salience"]'),
    ('Navajo (inalienable possession)', 'Prevents cognitively outsourcing system damage; problems are an inseparable part of one''s own system', 'Inseparability of system components', 'Language', 'Na-Dené / inalienable possession & animacy hierarchy', 'Strict distinction of alienable vs. inalienable possession; "I have a head" as a tool is impossible', '["possession", "inalienable", "integral"]', '["Possession & belonging"]'),
    ('Navajo (shape verbs & evidence)', 'Couples action to the geometry of the object and forces disclosure of one''s own certainty', 'Physical geometry of the world and the speaker''s certainty', 'Language', 'Na-Dené / evidential moods & shape verbs', 'Verbs for moving/giving change their root by shape (long-flexible, flat-elastic, round-compact); aspect moods disclose the degree of certainty', '["shape-verb", "geometry", "certainty"]', '["Object boundaries", "Evidence & certainty"]'),
    ('Cherokee (Tsalagi)', 'Forces permanent physical reality-checking: the state of aggregation must be carried syntactically', 'Physical geometry and consistency in space', 'Language', 'Iroquoian / classificatory handling verbs', 'No abstract "give"/"have"; the verb changes by whether the object is liquid, long-rigid, living, rope-like or a lump', '["classificatory-verb", "consistency", "geometry"]', '["Object boundaries"]'),
    ('Lakota (instrumental prefixes)', 'One root gives kabléča (shatter by a blow), nabléča (with the foot), yabléča (by biting), yubléča (with the hand): the event cannot be named before the force is named. Where Navajo and Cherokee vary the verb by the shape of the thing handled, this varies it by the energy applied, so a report cannot state that something broke and leave open what did the breaking', 'By which force a change of state came about', 'Language', 'Siouan / instrumental prefixes on bound verb roots', 'Seven frequent prefixes fix the means on the verb stem itself — ka- by a blow, na- by foot or by spontaneous inner force, pa- by pushing, wa- by a blade, wo- by piercing or shooting, ya- by mouth or teeth, yu- by hand — and for most of these stems no prefix-less form is in use', '["instrumental", "force", "means", "bound-root", "causal"]', '["Causality"]'),
    ('Basque (Euskara)', 'Removes the grammatical basis for premature blame assignment', 'System state instead of agency', 'Language', 'isolate / purely ergative', 'Only the deliberately acting agent gets the ergative; an undirected rolling stone is treated like an object', '["ergative", "agency", "blame"]', '["Causality", "Agency & control"]'),
    ('Georgian (Kartuli)', 'Rules out the concept of the total, controlling ego', 'The human as a resonance space, not a causer', 'Language', 'South Caucasian / split-ergative & inversion', 'With psych verbs the syntax flips: not "I love her" but "she is mine as a beloved object" (I in the dative)', '["inversion", "ergative-split", "psych-verb"]', '["Perspective & reciprocity", "Agency & control"]'),
    ('Tagalog', 'Forces grasping the scenario flexibly from any perspective as the center', 'Dynamic center of the event', 'Language', 'Austronesian / symmetrical voice (focus) system', 'Neither active nor passive dominates; the verb determines which role (actor, object, place, instrument, beneficiary) is the lead', '["voice-system", "role", "focus-system"]', '["Perspective & reciprocity", "Rank & salience"]'),
    ('Hawaiian (a/o possession)', 'No "my" without deciding whether the thing hangs on me or I on it, so control and origin stop collapsing into one relation', 'Direction of dependency in every possessive relation', 'Language', 'Austronesian (Polynesian) / two possessive classes by direction of dependency', 'Two possessive classes: the a-class for what was acquired or is controlled (kaʻu puke — my book), the o-class for what one springs from or belongs to (koʻu makuahine — my mother, koʻu inoa — my name)', '["possession", "a-o-class", "dependency", "control"]', '["Possession & belonging", "Agency & control"]'),
    ('Pohnpeian (possessive classifiers)', 'Forces stating what the having is for, so "we have X" cannot stand as one undifferentiated relation', 'What the possessor means to do with the thing', 'Language', 'Micronesian (Oceanic) / possessive classifiers by intended use', 'More than twenty possessive classifiers select by the relation of use rather than by separability: kene for what is to be eaten, nime for what is to be drunk, with further classes for vehicles, dwellings, plantings and kin; the same noun takes another classifier when the intended use changes', '["possession", "possessive-classifier", "use-relation", "edible", "drinkable"]', '["Possession & belonging", "Object boundaries"]'),
    ('Dyirbal (noun classes)', 'Prevents viewing things in isolation', 'Cosmic and material belonging', 'Language', 'Pama-Nyungan / radical noun classes', 'Four noun classes (incl. "women, fire and dangerous things"); every noun is at once mythologically-functionally classified', '["noun-classes", "classification"]', '["Object boundaries", "Possession & belonging"]'),
    ('Dyirbal (syntactic ergativity)', 'Refuses to carry an actor through a chain of events unchanged: whoever is to remain the through-line must first be grammatically demoted to undergoer', 'Which participant may be the through-line of a clause chain', 'Language', 'Pama-Nyungan / absolutive pivot with antipassive repair', 'Clauses can only share an argument that is absolutive in each; to keep an actor as the shared topic the verb must be antipassivised (-ŋay), which demotes that actor into the absolutive — Dixon''s classic analysis', '["syntactic-ergativity", "pivot", "antipassive", "topic-chain", "voice"]', '["Rank & salience", "Agency & control"]'),
    ('Ewe (logophoric pronouns)', 'A report cannot leave open whether it speaks of the one quoted or of a third party; the anchor of the perspective is carried on the pronoun itself', 'Anchor of the viewpoint in a report', 'Language', 'Niger-Congo (Kwa) / logophoric pronoun series', 'Inside reported speech a separate pronoun (yè) can refer only to the original speaker, while the ordinary pronoun in the same slot necessarily means someone else', '["logophoric", "reported-speech", "anchor", "perspective"]', '["Perspective & reciprocity", "Evidence & certainty"]'),
    ('Ewe (body-part locatives)', 'Forces stating which part of a thing a relation attaches to, so "in the system" cannot stand without deciding whether the thing has an inside, a top or a back at all', 'Space as borrowed anatomy', 'Language', 'Niger-Congo (Kwa) / body-part nouns as the locative resource', 'Spatial relations run through body-part nouns projected onto the object instead of abstract prepositions: megbé (back) → behind it, ta (head) → on top of it, dome (belly) → inside or among', '["body-part-locative", "postposition", "anatomy", "space"]', '["Space & orientation", "Object boundaries"]'),
    ('Wolof (focus conjugation)', 'No sentence without declaring where its weight lies; the participants stay untouched and only the emphasis is forced, which German carries invisibly in word order and stress', 'The highlighted element as a compulsory declaration', 'Language', 'Niger-Congo (Atlantic) / conjugation by focus rather than tense', 'The verbal complex is picked according to which element carries the focus — subject, predicate or complement — while tense rides along secondarily', '["focus-conjugation", "information-structure", "emphasis", "highlighting"]', '["Perspective & reciprocity", "Rank & salience"]'),
    ('Swahili (noun classes)', 'Reclassifies instead of classifying: moving a stem into another class re-sorts the entire sentence via concord', 'Mode of existence as a movable slot', 'Language', 'Niger-Congo (Bantu) / productive noun-class shifting', '15 to 18 noun classes whose agreement runs through the whole clause; the same stem is moved between classes: mtoto (child) becomes kitoto (small child) and utoto (childhood as a quality)', '["noun-classes", "concord", "reclassification", "derivation"]', '["Object boundaries", "Perspective & reciprocity"]'),
    ('Luganda (graded tense)', 'Forces disclosing the distance of an event; a claim about today and one about a distant epoch cannot share a form', 'Distance of an event instead of its position on a time line', 'Language', 'Niger-Congo (Bantu) / graded temporal remoteness', 'Several distinct pasts and futures by remoteness (today / since yesterday / remote); the verb form states how far away an event lies, not merely that it lies behind', '["remoteness", "graded-tense", "distance", "tense"]', '["Time & aspect"]'),
    ('Khoekhoe (clusive we)', 'Nobody can say "we" without settling whether the person addressed stands inside or outside the group, and whether two or many are meant', 'Membership of the addressee in every "we"', 'Language', 'Khoe-Kwadi (areal "Khoisan") / person-gender-number markers with clusivity & dual', 'Person-gender-number markers attach to the nominal itself; the first person forces the choice between a "we" that includes the addressee and one that shuts them out, and carries its own dual beside the plural', '["clusivity", "inclusive-exclusive", "dual", "person-marking"]', '["Possession & belonging", "Perspective & reciprocity"]'),
    ('Biblical Hebrew', 'Past and future behave like relational states, not a time line', 'Processual status instead of chronology', 'Language', 'Afro-Asiatic (Semitic) / radical aspectuality', 'No true tenses, only perfect (completed) and imperfect (uncompleted); the waw-consecutive flips the aspect in the narrative flow', '["aspect", "perfect-imperfect", "waw"]', '["Time & aspect"]'),
    ('Arabic (root & pattern)', 'Forces stating which derivation of a root is meant — causing, undergoing, seeking or doing mutually — instead of letting one word cover all of them', 'Derivational family instead of the isolated term', 'Language', 'Afro-Asiatic (Semitic) / root-and-pattern derivation', 'A triconsonantal root carries the semantic field; fixed templates derive the variants: kataba (write), kattaba (make write), kātaba (correspond with), takātaba (write to one another), istaktaba (ask to have written)', '["root-pattern", "derivation", "causative", "reciprocal"]', '["Causality", "Agency & control"]'),
    ('Amharic (converb chains)', 'Forces deciding which single event of a sequence is actually asserted and which are demoted to accompaniment, instead of letting a row of equal main clauses suggest that everything is claimed alike', 'The one event that carries the assertion', 'Language', 'Afro-Asiatic (Ethiosemitic) / converb chains with a single finite anchor', 'Long chains of non-finite converbs run up to one closing finite verb; only that last verb bears tense, mood and person, every earlier event hangs on it grammatically', '["converb", "non-finite", "chaining", "anchor"]', '["Causality", "Coexistence"]'),
    ('Oromo (marked nominative)', 'Reverses the burden of marking: not being-affected but acting is the case that has to be signalled, so an agent cannot slip into the sentence unnoticed', 'The actor as the marked deviation, not the default', 'Language', 'Afro-Asiatic (Cushitic) / marked nominative', 'The nominative of the acting subject is the specially marked form while object and citation form stay bare — the reverse of the accusative pattern', '["marked-nominative", "case", "agent", "alignment"]', '["Agency & control", "Causality"]'),
    ('Hausa (pluractional verbs)', 'Separates how often something happened from how many were affected, so one act with many affected parties cannot pass as many separate acts', 'Number and distribution of the event, not of its participants', 'Language', 'Afro-Asiatic (Chadic) / pluractional verb stems', 'A reduplicated verb stem marks that an action happened repeatedly or separately to each participant: gyara (repair) becomes gyaggyara (repair many, repair again and again)', '["pluractional", "event-number", "distribution", "reduplication"]', '["Time & aspect", "Coexistence", "Object boundaries"]'),
    ('Ancient Greek (aorist & middle voice)', 'Separates the shape of unfolding from time and softens the actor-patient dualism', 'Geometric shape of an action', 'Language', 'Indo-European (Hellenic) / aspect dominance & middle voice', 'The aorist shows an action as a timeless point; the middle voice makes the subject the space/participant of the action (neither actor nor patient)', '["aorist", "middle-voice", "aspect"]', '["Time & aspect", "Perspective & reciprocity"]'),
    ('Ancient Greek (article & substantivization)', 'Lets a property, an activity or an entire statement be handled as a thing that can itself be predicated of and counted', 'Anything as a bounded object of thought', 'Language', 'Indo-European (Hellenic) / article-driven substantivization', 'The article nominalizes any element — adjective, participle, adverb, whole clause: τὸ ὄν (that which is), τὸ καλόν (the beautiful), τὰ νῦν (the present circumstances), τὸ ἐμὲ λέγειν (my speaking)', '["article", "substantivization", "nominalization", "abstraction"]', '["Object boundaries", "Logic & ambiguity"]'),
    ('Ancient Greek (particles)', 'No step may stand unrelated, and the kind of link must be chosen; μέν … δέ forces every point to be given a counterweight before the next follows', 'Declared relation of every step to the previous one', 'Language', 'Indo-European (Hellenic) / obligatory discourse particles', 'Postpositive particles occupy a fixed second-position slot and name the link: μέν … δέ (paired counterweight), γάρ (ground), ἄρα (inference drawn), δή (as granted), μέντοι (concession)', '["particles", "discourse-relation", "counterweight", "concession"]', '["Causality", "Coexistence"]'),
    ('Latin (ablative absolute)', 'Separates the accompanying circumstance from the assertion while withholding the link, so the relation must be decided deliberately instead of slipping in as a "because"', 'Circumstance without a named relation', 'Language', 'Indo-European (Italic) / participial adjunct without a stated relation', 'A noun plus participle in the ablative hangs a whole circumstance beside the clause without saying whether it is cause, time, condition or concession (urbe capta — "the city having been taken")', '["ablative-absolute", "participle", "adjunct", "unstated-relation"]', '["Causality", "Coexistence"]'),
    ('Latin (gerundive of obligation)', 'Turns "I must do X" into "X is to be done", so what is required stands apart from whoever is responsible — and whether anyone is named at all becomes visible', 'Obligation as a property of the matter, not a decision of the doer', 'Language', 'Indo-European (Italic) / passive periphrastic with dative agent', 'The gerundive makes the task a predicate of the thing while the doer sinks into the dative: mihi liber legendus est ("the book is to-be-read by me"), and may be omitted entirely: delenda est Carthago', '["gerundive", "obligation", "dative-agent", "agentless"]', '["Agency & control", "Possession & belonging"]'),
    ('Latin (oratio obliqua)', 'A claim taken over from someone else cannot be phrased like one''s own; the borrowed portion stays morphologically marked down to its last clause', 'Foreign claims marked as foreign across a whole passage', 'Language', 'Indo-European (Italic) / reported speech in infinitive & subjunctive', 'Reported content switches into accusative-plus-infinitive and its subordinate clauses into the subjunctive, for as long as the report runs (dixit urbem captam esse)', '["oratio-obliqua", "reported-speech", "subjunctive", "attribution"]', '["Evidence & certainty", "Perspective & reciprocity"]'),
    ('Hopi', 'Replaces the time line with the degree of realization', 'Objective manifestation vs. subjective potential', 'Language', 'Uto-Aztecan / temporal absence', 'Distinguishes not yesterday/today/tomorrow but the already manifested (facts) vs. the still-manifesting (future, wish, thought)', '["manifestation", "potential", "realization"]', '["Time & aspect", "Evidence & certainty"]'),
    ('Russian', 'Hardly any action is expressible without committing to process or the final result', 'Fundamental nature of the result / manner of unfolding', 'Language', 'Indo-European (Slavic) / binary verbal aspect', 'Almost every verb as a pair: perfective (completed, goal-directed) and imperfective (ongoing, processual)', '["aspect", "unfolding", "process"]', '["Time & aspect"]'),
    ('Polish (instrumental predication)', 'Splits "X is Y" into two claims that cannot be conflated — occupying a category in some capacity, or having a property — so a definition cannot pass itself off as a description', 'Whether a predicate assigns a category or states a property', 'Language', 'Indo-European (Slavic) / case-marked predicate nouns', 'A predicate noun after "to be" goes into the instrumental, the case of "in the capacity of" (on jest nauczycielem — he is a teacher), while a predicate adjective stays nominative (on jest wysoki); the presenting construction to jest X keeps the nominative, so labelling and characterising cannot be the same sentence', '["case", "instrumental", "predication", "category", "copula"]', '["Object boundaries", "Logic & ambiguity"]'),
    ('Polish (numeral threshold)', 'Forces a threshold at which counted individuals stop being a plurality and become an amount, so the affected and the figures cannot be the same kind of thing', 'Where a set of individuals turns into a quantity', 'Language', 'Indo-European (Slavic) / quantified phrases split at four', 'Two to four take the plural and agree as a plural subject (trzej chłopcy grali); from five on the counted noun stands in the genitive plural and the whole phrase takes third-person neuter singular agreement (pięć osób przyszło), so it is handled as one quantified mass rather than a set of individuals', '["numeral", "quantification", "threshold", "genitive", "agreement"]', '["Object boundaries", "Rank & salience"]'),
    ('Polish (masculine-personal plural)', 'No group can be put in the plural without settling whether at least one man is among them, and one member''s property is projected onto the whole collective', 'Whether a group counts as containing a human male', 'Language', 'Indo-European (Slavic) / masculine-personal vs non-masculine-personal plural', 'Every plural splits into masculine-personal and everything else, and plural past-tense verbs, adjectives and pronouns follow the split: chłopcy byli / oni against kobiety, dzieci, psy and stoły były / one — women, children, animals and things share one form; the category resolves rather than counts, so one man among a thousand women flips the whole form', '["gender", "masculine-personal", "plural", "agreement", "resolution"]', '["Rank & salience", "Object boundaries"]'),
    ('Finnish (partitive object)', 'Forces stating how far an action got through the case of what it touched, so an activity cannot be reported as a finished result without settling whether the thing was reached whole or only in part', 'Completion carried by the object, not the verb', 'Language', 'Uralic (Finnic) / partitive vs. total object', 'The object case decides how far the action got: luin kirjan (read the book through) against luin kirjaa (was reading at the book); an unbounded or partial quantity takes the same partitive (join veden / join vettä), and under negation every object turns partitive, so a denial cannot leave its object whole; Estonian marks the same contrast', '["partitive", "total-object", "boundedness", "aspect", "case", "negation-scope"]', '["Time & aspect", "Object boundaries"]'),
    ('Hungarian (associative plural)', 'Separates a peer set from a focal element with its dependants before anything else is said about the group: three servers and the primary with its replicas are the same count and a different structure, and the plain plural cannot say the second', 'Whether a group is a set of equals or one member plus what belongs to it', 'Language', 'Uralic (Ugric) / associative plural', 'Beside the ordinary plural -k stands -ék: Jánosok is several people called János, Jánosék is János and the people belonging to him; naming a group forces the choice between the two', '["associative-plural", "plural", "grouping", "dependency", "salience"]', '["Coexistence", "Rank & salience"]'),
    ('Tuyuca', 'Prevents smuggling opinions in as facts', 'Verifiable origin of information', 'Language', 'Tucanoan / obligatory evidentiality', 'No sentence without one of five endings for the source: seen, heard, inference, hearsay, assumption', '["evidentiality", "source", "verification"]', '["Evidence & certainty"]'),
    ('Wintu', 'Binds every statement to the speaker''s epistemic responsibility', 'Cognitive responsibility of the speaker', 'Language', 'Penutian / epistemic evidentiality', 'Distinguishes knowledge from one''s own senses vs. from inference/intuition; the verb encodes whether one felt the fever or only read it off', '["evidentiality", "senses", "responsibility"]', '["Evidence & certainty"]'),
    ('Japanese', 'The agent-patient sentence becomes a mere statement about a state', 'Topic instead of agent', 'Language', 'topic-prominent language', 'wa topic marking separates the topic from the subject; agents can be dropped', '["topic", "wa", "agentless"]', '["Perspective & reciprocity", "Rank & salience"]'),
    ('Japanese (listing particles)', 'A list cannot be handed over without declaring its own completeness. In requirements work the two particles separate "these are the stakeholders" from "these are stakeholders among others" — a difference German und leaves open and that surfaces later as a gap nobody agreed to', 'Whether an enumeration is closed or only exemplary', 'Language', 'Japonic / exhaustive vs. representative listing', 'Joining nouns forces a choice of particle: hon to pen names exactly the book and the pen and nothing else, hon ya pen names both as examples of a larger set that stays unspoken (often closed with nado); there is no neutral "and" to fall back on', '["coordination", "listing", "exhaustive", "completeness", "particles"]', '["Coexistence", "Logic & ambiguity"]'),
    ('Yucatec Maya', 'Brings into view what counts as a bounded unit at all', 'Material instead of count', 'Language', 'classifier language', 'Nouns count as unbounded material; individuation is expressed via a classifier', '["classifier", "material", "individuation"]', '["Object boundaries"]'),
    ('Kayardild (modal case)', 'Stamps the tense, mood and polarity of the whole clause onto every non-subject nominal, so no participant can sit in a sentence temporally uninvolved', 'The temporal frame carried by every participant, not by the verb', 'Language', 'Tangkic (Australia) / case as a carrier of tense-mood-polarity', 'Nominals take up to four stacked case-like suffixes; one layer, Evans'' "modal case", is selected by the clause''s tense-mood-polarity, so a future or a negated clause re-inflects every non-subject noun and its modifiers; under "verbal case" nominals take verbal endings and agree in tense with the main verb while staying syntactically nominal', '["case-stacking", "modal-case", "polarity", "tam", "case"]', '["Time & aspect", "Coexistence"]'),
    ('Berik (diurnal tense)', 'Binds a statement to the light conditions under which the event happened, so nothing can be claimed in a flat, condition-free present', 'Position in the day-night cycle instead of on a time line', 'Language', 'Tor-Kwerba (Papua, Indonesia) / diurnal verbal marking', 'The verb carries whether the event fell in daylight or in darkness, bundled with the number and size of the object and the recipient: kitobana — "he gives three large objects to a male in the sunlight"', '["diurnal", "cycle", "observation-conditions", "tense", "size"]', '["Time & aspect", "Object boundaries"]'),
    ('Jingulu (three light verbs)', 'Forces every action to resolve into coming, going or neither, so no event can be named without settling its direction relative to a reference point', 'Direction as the obligatory core of every action', 'Language', 'Mirndi / West Barkly (Australia) / complex predicates on three inflecting verbs', 'Only three inflecting verbs — do, go, come; all further meaning sits in an uninflecting root while the light verb carries tense, mood, aspect and associated motion (come as approach, go as withdrawal, do as stasis)', '["light-verb", "complex-predicate", "direction", "decomposition", "associated-motion"]', '["Space & orientation", "Causality"]'),
    ('Tzeltal (uphill-downhill axis)', 'Forces every relation onto one fixed asymmetric gradient: two elements cannot be set beside each other without settling which of them lies further up the slope, so a flat side-by-side arrangement is not available', 'A fixed gradient of the land as the primary spatial axis', 'Language', 'Mayan / absolute terrain-based orientation', 'Space runs on ajk''ol (uphill), alan (downhill) and a residual across axis taken from the overall slope of the territory rather than from the visible local incline; there is no left/right and no cardinal set, and the axis is kept indoors, on flat ground and in rotated arrays — Brown and Levinson''s Tenejapa studies', '["terrain", "uphill-downhill", "absolute-orientation", "gradient", "landscape"]', '["Space & orientation"]'),
    ('Yoruba (serial verbs)', 'Refuses to let a chain be split into separately marked steps: one tense and one negation cover the whole series, so the links must be construable as a single event and their relations have to be inferred instead of being named by a "because" or an "in order to"', 'An event chain that has to hold as one single event', 'Language', 'Niger-Congo (Volta-Niger) / serial verb constructions', 'Several bare verbs share one subject and a single tense-aspect-negation specification with no linker between them: ó fi ọbẹ gé ẹran ("he took knife cut meat"), alongside comitative bá and directional or resultative series; which relation holds between the links — instrument, purpose, result, direction, beneficiary — is left unexpressed', '["serial-verb", "monoclausal", "linker-less", "tam-sharing", "instrument", "event-chain"]', '["Causality", "Coexistence"]'),
    ('Mano (auxiliary series)', 'Denial cannot be graded as finely as assertion: what is claimed arrives already sorted by aspect and mood in the slot right after the subject, while what is refused loses that sorting and has to have it rebuilt further along the clause, so affirming and negating are not mirror images of one another', 'Assertion graded finely where denial is not', 'Language', 'Mande (South) / subject-indexing auxiliaries in TAMP series', 'Every clause runs S – AUX – (O) – V with an auxiliary that indexes the subject''s person and number and belongs to one of eleven series — perfect, past, existential, imperfective, conjoint, negative, conjunctive, prohibitive, subjunctive, prospective, dubitative — so the series is chosen in the second slot, before object and verb, while the full tense-aspect-mood-polarity value is carried by the construction as a whole; some series are told apart by tone alone (lɛ́ɛ̀ 3sg.ipfv against lɛ̀ɛ́ 3sg.neg), past auxiliaries and the negative particle fuse with a third person singular object (ē 3sg.pst against ā 3sg.pst>3sg), and a single negative series covers the negative perfective, imperfective, imperfect, future and irrealis alike, the distinctions it drops being rebuilt by particles and verb forms elsewhere in the clause — gbā for the perfective, nɛ́ŋ̀ "not yet" for the perfect, the auxiliary kɛ̄ plus an infinitive for the imperfect; Khachaturyan''s Mano grammar', '["auxiliary-series", "tam", "polarity", "person-marking", "negation-asymmetry", "portmanteau", "tone"]', '["Time & aspect", "Logic & ambiguity"]'),
    ('Ithkuil', 'Forces a mathematical triage of one''s own thought', 'Elimination of ambiguity; hyper-precise categorization', 'Constructed language', 'philosophically constructed (a posteriori/a priori)', 'One word-complex encodes multi-layered logical distinctions; forces stating whether a consequence is intended, unintended, physically forced or psychologically conditioned', '["constructed", "precision", "triage"]', '["Logic & ambiguity", "Causality"]'),
    ('Lojban', 'Makes misunderstandings from unclear causal links syntactically impossible', 'First-order predicate logic as syntax', 'Constructed language', 'logically constructed language (loglang)', 'No split between noun and verb; everything predicates; syntactically free of ambiguity, parseable like formulas', '["logic", "predicate", "unambiguous"]', '["Logic & ambiguity", "Causality"]'),
    ('Toki Pona', 'Acts like a radical word ban against bureaucratic obfuscation', 'Radical reduction to the essence of the moment', 'Constructed language', 'minimalist constructed (philosophical game)', 'Only ~120–137 words; breaks overloaded concepts into primitive blocks ("car" = "moving container")', '["minimalism", "reduction", "word-ban"]', '["Object boundaries"]');
INSERT INTO forms
    (name, description, focus, category, classification, feature, tags, themes)
VALUES
    ('Haiku', 'Rules out causal chains and reduces a problem to a state image that the cut breaks open dialectically', 'Snapshot-like presentness; collision of two images', 'Poetic form', 'Japanese short form (5-7-5 morae)', 'Kigo (season word) and kireji (cutting word); two images without a connective', '["juxtaposition", "cut", "compression"]', '["Causality", "Coexistence"]'),
    ('Tanka', 'Perfect for separating objective system observation from subjective evaluation/solution', 'Asymmetric dialogue between observation and reaction', 'Poetic form', 'Japanese form (5-7-5-7-7)', 'The first three lines (kami-no-ku) raise an image, the last two (shimo-no-ku) answer', '["dialogue", "asymmetry", "observation"]', '["Perspective & reciprocity"]'),
    ('Pantun', 'Mirrors the problem through an alien, organic metaphor to unlock subconscious solution paths', 'Lateral thinking via associative bridges', 'Poetic form', 'Malay-Indonesian quatrain (ABAB)', 'The first two lines (pembayang) paint a seemingly irrelevant nature image, the last two (maksud) state the actual point', '["metaphor", "association", "lateral"]', '["Perspective & reciprocity"]'),
    ('Sestina', 'Forces relating 6 core factors of a problem in every conceivable configuration', 'Obsessive circling around fixed variables', 'Poetic form', 'Occitan troubadour form / permuted end-words', '6 stanzas of 6 lines plus a tercet; the 6 end-words recur in mathematically permuted order, no rhymes', '["permutation", "end-word", "combinatorics"]', '[]'),
    ('Ghazal', 'Each couplet stands alone; breaks the narrative "A follows B" into a mosaic view', 'Fragmented independence within a thematic bracket', 'Poetic form', 'Persian-Arabic form / autonomous couplets with radif', 'Autonomous couplets with a fixed end-rhyme and an identical refrain word (radif) at the end of each couplet', '["couplet", "radif", "mosaic", "repetition"]', '["Coexistence"]'),
    ('Rubāʿī', 'Forces a sharpened resolution in a single quatrain', 'Epigrammatic sharpening and paradox resolution', 'Poetic form', 'Persian quatrain (AABA)', 'Lines 1–2 build the problem, line 3 swerves out (tension), line 4 strikes with the solution', '["quatrain", "epigram", "inversion"]', '[]'),
    ('Grianan', 'Forces the search for phonically fitting synonyms one would never otherwise choose', 'Acoustic interweaving of key terms', 'Poetic form', 'Irish bardic tradition / syllable- and vowel-counted', 'Prescribes extreme internal rhymes and alliteration', '["internal-rhyme", "alliteration", "sound"]', '[]'),
    ('Skaldic Dróttkvætt', 'Forces decomposing a problem into riddle images (e.g. "sword-sea" for blood) and thus into abstraction', 'Hyper-encrypted mathematical predication', 'Poetic form', 'Old Norse skaldic / complex stanza meter', '6 syllables per line, internal rhymes (aðalhending), half-rhymes (skothending), kennings (riddle words)', '["skaldic", "kenning", "compression"]', '["Perspective & reciprocity"]'),
    ('Minnesang (canzone form)', 'The Stollen light two facets of the same deficit, the Abgesang breaks the structure onto a new level', 'Dialectical verification through broken symmetry; relationship/reciprocity', 'Poetic form', 'Middle High German canzone form (AAB)', 'Two identically built Stollen (Aufgesang) and a differently structured Abgesang (AAB); wooing I-you orientation', '["stollen-abgesang", "broken-symmetry", "dialogic"]', '["Perspective & reciprocity"]'),
    ('Shloka', 'Builds a problem as a balanced scale in which cause and effect face off cleanly', 'Even, meditative balancing of opposites', 'Poetic form', 'Sanskrit epic / distichs of 16 syllables (4 pādas)', 'Two lines of 16 syllables, split into four quarters (pādas), with fixed rhythms at the seams', '["distich", "balance", "symmetry"]', '["Causality", "Perspective & reciprocity"]'),
    ('Kanshi', 'Unlike thesis-antithesis-synthesis the ten lifts the problem to a higher level instead of fighting it', 'Dramaturgical four-step process', 'Poetic form', 'Japanese-Chinese form / kishōtenketsu', '4 lines: introduction, development, turn (ten), resolution; line 3 introduces an unexpected third element', '["kishotenketsu", "turn", "four-step"]', '["Perspective & reciprocity"]'),
    ('Shakespearean Sonnet', 'Forces multi-stage unfolding with a pointed final thesis', 'Cascading argument with a final epigrammatic strike', 'Poetic form', 'English sonnet form (ABAB CDCD EFEF GG)', 'Three quatrains enumerate three dimensions of the problem, the closing couplet (GG) throws down the radical truth in two lines', '["sonnet", "quatrain", "cascade", "compression"]', '[]'),
    ('Villanelle', 'Shows how a system turns in circles until the refrains create unbearable urgency', 'Circular loop with echoing amplification', 'Poetic form', 'French form / 19 lines with two refrains', 'Five tercets plus a quatrain; lines 1 and 3 of the first stanza recur alternately as refrains', '["refrain", "loop", "repetition", "recursion"]', '[]'),
    ('Triolet', 'Forces achieving maximum structural effect with minimal substance', 'Structural economy through refrain', 'Poetic form', 'medieval French / eight lines (ABaAabAB)', 'Line 1 recurs as the 4th and 7th, line 2 as the 8th', '["refrain", "repetition", "economy"]', '[]'),
    ('Rondo (Rondeau)', 'Prevents cognitive drift: after each analytical idea the form forces a return to the opening statement', 'Permanent return to the core problem after each excursion', 'Poetic form', 'classical text/music form (ABACADA)', 'A fixed refrain (A) alternates with ever-new episodes (B, C, D)', '["refrain", "return", "focus"]', '[]'),
    ('Canso', 'The first sentence determines the phonetic fate of all others; thoughts are subordinated to the acoustic form', 'Acoustic pre-programming of subsequent thoughts', 'Poetic form', 'troubadour poetry / coblas with tornada', 'The rhymes of the first stanza dictate the vowels/consonants of all following stanzas; often a closing tornada', '["coblas", "rhyme", "sound-constraint"]', '[]'),
    ('Englyn', 'Forces fitting the next phase of consideration into the current clause', 'Anticipatory overlap of sense units', 'Poetic form', 'Welsh traditional meter / exact syllable count (10-6-7-7)', 'The first rhyme falls mid-line 1; the rest of the line must anticipate the theme of line 2', '["syllable-count", "anticipation", "nesting"]', '[]'),
    ('Glosa', 'Forces the whole analysis into the corset of serving a foreign quote exactly', 'Microscopic exegesis of a source text', 'Poetic form', 'Spanish Baroque / texto plus four décimas', 'A given quatrain quote is dissected by four ten-line stanzas; each stanza must end exactly with one of the four lines', '["quote", "exegesis", "combinatorics"]', '["Perspective & reciprocity"]'),
    ('Chant Royal', 'Every argument culminates in the same refrain; the envoi forces the compressed essence to the highest instance', 'Hierarchical address under maximal formal pressure', 'Poetic form', 'French form / five eleven-line stanzas plus envoi', 'An identical refrain ends each stanza; a closing envoi to a "Prince"', '["refrain", "envoi", "hierarchy"]', '["Rank & salience"]'),
    ('Antibacchius', 'Prevents gliding along clichés like "leads to" or "because" and forces a deliberative process', 'Cognitive jam and deceleration of causal rhetoric', 'Metrical foot', 'ancient meter (long, long, short)', 'Two heavy longs at the start block the forward drive before a short relief follows', '["meter", "foot", "deceleration"]', '["Causality"]'),
    ('Bacchius', 'Introduces a problem gently to end it in two heavy terms', 'Crescendo of the argument; retarding moment', 'Metrical foot', 'ancient meter (short, long, long)', 'Inversion of the antibacchius: a gentle start, ending in two unyielding heavy terms', '["meter", "foot", "crescendo", "inversion"]', '[]'),
    ('Choriamb', 'The metrical shock in the middle suits breaking dogmatic argument chains structurally', 'Syncopated rhythmic disturbance; pincer grip', 'Metrical foot', 'ancient lyric (long, short, short, long)', 'Encloses two fleeting shorts between two rigid longs', '["meter", "foot", "syncope", "disruption"]', '[]'),
    ('Anapest', 'Removes static dwelling and forces a stuck problem into a flowing dynamic', 'Forward-driving, galloping dynamic', 'Metrical foot', 'ancient/classical meter (short, short, long)', 'Two unstressed syllables, then a stressed one', '["meter", "foot", "dynamic"]', '["Time & aspect"]'),
    ('Dactyl', 'Perfect for analysis from large to small: the heavy core problem stands first, details flow off after', 'Falling, descending structuring', 'Metrical foot', 'ancient meter / Homeric epic (long, short, short)', 'One stressed, two unstressed syllables', '["meter", "foot", "decomposition", "top-down"]', '[]'),
    ('Amphibrach', 'Interrupts linear expectation: no progressive pressure but dwelling around a fixed point', 'Centering and cyclical balance', 'Metrical foot', 'symmetrical triple (short, long, short)', 'Heavy stress in the middle, framed by two shorts; a rocking, returning movement', '["meter", "foot", "balance", "centering"]', '[]'),
    ('Parallelismus Membrorum', 'Every argument must be mirrored immediately; prevents one-dimensional tunnel thinking', 'Stereoscopic depth of a concept', 'Rhetorical figure', 'Ancient Hebrew psalms / thought-rhyme', 'A statement in line A is repeated synonymously in line B, contrasted antithetically, or synthetically extended', '["thought-rhyme", "mirroring", "antithesis"]', '["Perspective & reciprocity"]'),
    ('Chiasmus', 'Reverses the causal vectors to uncover hidden dependencies', 'Inversion of priorities', 'Rhetorical figure', 'classical rhetoric / crosswise placement (A-B:B-A)', 'Crosswise placement of corresponding parts ("eat to live, not live to eat")', '["crosswise", "inversion", "dependency"]', '["Causality"]'),
    ('Litany / Anaphora', 'The monotone recitation washes away verbal ornament so deep-seated system faults crystallize', 'Hypnotic emptying of the ego; rhythmic trance', 'Rhetorical figure', 'sacral / repetitive anaphora', 'Endless repetition of the same sentence opening, varied only by a changing variable at the end', '["anaphora", "repetition", "trance"]', '[]'),
    ('Ghazal chain (anadiplosis)', 'Prevents mental jumps: no new argument without the last word of the old one as foundation', 'Gapless chaining without evolutionary jumps', 'Rhetorical figure', 'anadiplosis structure / chaining', 'The last word of a line/stanza must be the first word of the next', '["anadiplosis", "chaining", "cohesion"]', '["Causality"]'),
    ('Kenning structure', 'Rename the components of your problem ("data-lung" for a server) to break the habitual distance', 'Estrangement of the familiar via relational renaming', 'Rhetorical figure', 'early medieval Scandinavia / metaphorical periphrasis', 'Replaces a noun with a two-part metaphor ("whale-road" = sea, "battle-light" = sword)', '["kenning", "metaphor", "renaming"]', '["Perspective & reciprocity"]'),
    ('Shaped poem / Calligramme', 'The geometry of the problem forces the line ending; thinking is steered by the visual corset', 'Fusion of semantics and typography', 'Visual form', 'antiquity/baroque / typographic form', 'The line lengths reproduce the physical shape of the object discussed (egg, cross, gear)', '["visual", "typography", "shape"]', '["Object boundaries", "Space & orientation"]'),
    ('Acrostic', 'Builds a vertical control axis that permanently disciplines the horizontal argument', 'Two-dimensional information encoding', 'Visual form', 'antiquity / vertical encoding', 'The initial letters/words of each line, read top to bottom, form a new word', '["acrostic", "vertical", "encoding"]', '[]'),
    ('Palindrome poem', 'Eliminates the arrow of time: beginning and end collapse, cause and effect become interchangeable', 'Absolute time-reversible symmetry', 'Visual form', 'Sator-square logic / symmetry', 'Sentences/stanzas read the same forward and backward', '["palindrome", "symmetry", "reversal"]', '["Time & aspect", "Causality"]'),
    ('Plato''s Allegory of the Cave', 'Forces viewing current measurements as mere "shadows on the wall" and seeking the true problem outside the familiar surface', 'Epistemic level shift', 'Narrative structure', 'allegorical structure / three-stage', 'Shadow paradise (deception), ascent (insight/pain), return (incomprehension of the crowd)', '["allegory", "insight", "levels"]', '["Evidence & certainty"]'),
    ('Frame narrative', 'Each symptom becomes its own sub-narrative with its own rules and encapsulates complexity modularly', 'Recursive nesting of meta-levels', 'Narrative structure', 'nesting (e.g. One Thousand and One Nights)', 'An outer narrative brackets an inner one, which in turn begets yet another', '["frame", "recursion", "nesting"]', '["Evidence & certainty"]'),
    ('Mise en abyme', 'Separates the merely nested from the self-repeating: unlike a frame bracketing a different story, here the inner level carries the same structure, so whatever holds of it must hold of the whole', 'The detail that repeats the whole', 'Narrative structure', 'heraldic device adopted for literature (Gide) / the part reproduces the whole', 'An element inside the work reproduces the structure of the work itself — the picture that contains the picture, the story whose inner story is its own', '["mise-en-abyme", "self-similarity", "reflexivity", "levels"]', '["Rank & salience"]'),
    ('Dialectical Midrash', 'The problem must not be harmonized; it demands letting incompatible analyses stand side by side', 'Multi-perspective ambiguity tolerance', 'Narrative structure', 'rabbinic exegesis / marginal commentaries', 'A core text is surrounded by independent, partly contradictory commentaries that all hold simultaneously', '["exegesis", "contradiction", "commentary"]', '["Logic & ambiguity", "Perspective & reciprocity"]'),
    ('Vedic Hymn (Rigveda)', 'Forces analyzing the "fault" in its functional role for the whole system (what does it involuntarily stabilize?)', 'Acceptance of the ambivalence of destructive forces', 'Narrative structure', 'Rigveda structure / hymnic enumeration', 'Enumeration of complementary cosmic forces that condition and destroy each other (Agni destroys and purifies)', '["hymn", "ambivalence", "forces"]', '["Perspective & reciprocity", "Logic & ambiguity"]'),
    ('Koan', 'Deliberately crashes rational SVO thinking to force intuitive insight beyond true/false', 'Short-circuiting the logical-analytical mind', 'Narrative structure', 'Zen Buddhism / paradox', 'A rationally unsolvable paradox ("What is the sound of one hand clapping?")', '["paradox", "zen", "intuition"]', '["Logic & ambiguity"]'),
    ('Fugue', 'Rules out treating the counter-position as a later chapter: statement and answer are developed in the same pass rather than in sequence, and the stretto tests whether the answer still holds when it arrives before the statement is complete', 'The counter-voice that has to run at the same time, not afterwards', 'Narrative structure', 'musical form adopted for text / dux answered by comes over a countersubject', 'A theme (dux) is stated and answered by a second voice a fifth away (comes) while the first voice keeps going against it as countersubject; the material may return inverted, augmented or diminished, and in the stretto the entries overlap before any voice has finished', '["counterpoint", "dux-comes", "simultaneity", "inversion", "stretto"]', '["Coexistence", "Perspective & reciprocity"]'),
    ('Incantatio', 'Phrase the problem as a binding decree ("I bind variable X to state Y") instead of a report; turns observation into responsibility', 'Radical assumption of intentional agency', 'Technique', 'Roman spell / performative speech act', 'Rigid rhythmic alliteration (carmen) meant to bind reality by being spoken', '["performative", "decree", "agency"]', '["Agency & control"]'),
    ('Cento', 'Bans your own words: foreign manuals, bug reports or quotes must be recombined until your own truth becomes visible', 'Pure recombination out of the deficit', 'Technique', 'Roman patchwork poem / pure recombination', 'The text consists solely of copied lines/phrases from other authors', '["collage", "recombination", "foreign-quote"]', '["Perspective & reciprocity"]'),
    ('Lipogram', 'Describing without certain words/letters fires areas that must lay entirely new conceptual paths', 'Circumventing a synaptic blockade', 'Technique', 'antiquity / Oulipo / letter ban', 'A given letter (e.g. "e") is banned throughout the text', '["oulipo", "letter-ban", "constraint"]', '[]'),
    ('S+7 (N+7)', 'Collapses the practised vocabulary of a field so only the relations between the slots remain: whatever still reads as an argument was carried by the structure, not by the terminology. Needs a fixed word list — without one the substitution is invented instead of counted and the result is not reproducible', 'The structural skeleton that stays readable once the familiar terms are gone', 'Technique', 'Oulipo (Lescure, 1961) / dictionary-based noun substitution', 'Every noun is replaced by the seventh noun following it in one named dictionary, counted mechanically, while syntax and function words stay untouched', '["oulipo", "substitution", "renaming", "constraint", "word-list"]', '[]'),
    ('Clinamen', 'Perec''s knight''s tour across the 10x10 building skips one square, which is why the book has 99 chapters and not 100. Name the rule a system imposes on itself, break it once at a point where compliance was still available, and read off what the exception costs: a rule whose breach changes nothing was never holding anything up', 'Whether a rule carries anything or is decoration', 'Technique', 'Oulipo (Perec, La Vie mode d''emploi) / one deliberate breach of one''s own constraint', 'A strict constraint is set up and then broken exactly once, on purpose; the Oulipo condition is that the breach may only be taken where the rule could still have been followed; the constraint has to come from somewhere else, so this is the one pattern that cannot be applied on its own — stacked on whichever lens is in use, it tests that lens', '["clinamen", "oulipo", "constraint", "exception", "broken-symmetry", "stacked-only"]', '["Logic & ambiguity"]'),
    ('Enumeration', 'Refuses the causal chain structurally and forces seeing things as coexisting rather than emerging from one another', 'Coexistence instead of causality', 'Register', 'prose register', 'Works without direction-asserting verbs', '["coordination", "coexistence", "states"]', '["Causality", "Coexistence"]'),
    ('Back-translation', 'Translate a passage into another language and back; what breaks was language-bound, what survives counts as more robust', 'Test the robustness of a formulation', 'Technique', 'thinking tool', 'Exposes language-bound idiosyncrasies via the detour through a foreign language', '["translation", "detour", "robustness"]', '[]'),
    ('Form-switch', 'Forces the same content into a foreign genre (a proof as a recipe, a process as a map), so connections the usual form concealed surface', 'Make concealed connections visible', 'Technique', 'thinking tool', 'A different genre forces different connections', '["genre", "transformation", "reframe"]', '[]'),
    ('Word ban', 'Bans a single word for a paragraph (because, leads to, any directional verb); whatever remains and holds was never dependent on the hierarchy', 'Test dependence on the causal structure', 'Technique', 'thinking tool', 'A targeted word ban exposes unnecessary hierarchy', '["word-ban", "constraint", "causal"]', '["Causality", "Agency & control"]'),
    ('Perspective swap', 'Recounts the same event from the viewpoint of the supposed object, so the ranking of actor and patient dissolves', 'Dissolve the ranking of agent and object', 'Technique', 'thinking tool', 'Shifts the viewpoint onto the grammatical object', '["perspective", "object", "ranking"]', '["Perspective & reciprocity", "Rank & salience"]'),
    ('Scale test', 'Tests a claimed self-similarity instead of asserting it: whatever forces its own vocabulary at one level is the place where the fractal analogy breaks and something genuinely new begins', 'Whether a level of a system has a description of its own', 'Technique', 'thinking tool', 'The description is written once and then required to hold at every level of the system; wherever a level needs vocabulary of its own, the self-similarity ends there', '["self-similarity", "scale-invariance", "levels", "recursion", "constraint"]', '["Rank & salience", "Coexistence"]'),
    ('Node collapse', 'Inverts the argument-slot logic: instead of filling places with things it empties them, so a statement about entities has to show what in it is more than the relations it asserts', 'What survives when the things are replaced by their relations', 'Technique', 'thinking tool / structuralist and structural-realist reduction', 'Every noun is rewritten as the bundle of relations it stands in until only the net remains; whatever cannot be dissolved is read off as the actual claim', '["relational", "structuralism", "node-free", "reduction", "residue"]', '["Object boundaries", "Logic & ambiguity"]');
